extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var validator = await instantiate_script("res://story/story_validator.gd")
	if not check("istanza", validator != null, "Lo script story_validator.gd deve potersi istanziare senza errori"):
		return
	if not check("metodi", has_function(validator, "validate_lines") and has_function(validator, "validate_chapter"), "StoryValidator deve implementare i metodi validate_lines e validate_chapter"):
		return
	var valid_res: Array = call_if_exists(validator, "validate_chapter", ["res://story/branching_story.json"], ["errore"])
	check("capitolo_valido", valid_res.is_empty(), "I capitoli validi del gioco non devono generare errori (trovati: %d)" % valid_res.size())
	var bad_speaker: Array = call_if_exists(validator, "validate_lines", [[
		{"type": "line", "speaker": "OmbraMisteriosa", "text": "Chi va la'?"}
	]], [])
	check("speaker_sconosciuto", not bad_speaker.is_empty(), "Un personaggio non in KNOWN_SPEAKERS deve essere segnalato")
	var bad_jump: Array = call_if_exists(validator, "validate_lines", [[
		{"type": "jump", "target": "porta_inesistente"}
	]], [])
	check("salto_inesistente", not bad_jump.is_empty(), "Un salto verso un'etichetta non dichiarata deve essere segnalato")

