class_name StoryValidator
extends RefCounted

const KNOWN_SPEAKERS: Array[String] = ["Elena", "Marco", "???", ""]


func validate_chapter(file_path: String) -> Array[String]:
	if not FileAccess.file_exists(file_path):
		return ["%s: File non trovato." % file_path]

	var file := FileAccess.open(file_path, FileAccess.READ)
	if not file:
		return ["%s: Impossibile aprire il file." % file_path]

	var json_data: Variant = JSON.parse_string(file.get_as_text())
	if not json_data is Dictionary:
		return ["%s: JSON non valido o non è un dizionario." % file_path]

	var data: Dictionary = json_data
	if not data.has("lines") or not data["lines"] is Array:
		return ["%s: Chiave 'lines' mancante o non valida." % file_path]

	return validate_lines(data["lines"])


func validate_lines(lines: Array) -> Array[String]:
	var errors: Array[String] = []
	var declared_labels: Array[String] = []

	# 1. Raccoglie tutte le etichette dichiarate
	for item in lines:
		if item is Dictionary and item.get("type", "") == "label":
			var label_id: String = String(item.get("id", item.get("name", "")))
			if not label_id.is_empty() and not declared_labels.has(label_id):
				declared_labels.append(label_id)

	# 2. Controlla ogni comando
	for i in range(lines.size()):
		var item: Variant = lines[i]
		if not item is Dictionary:
			continue
		var cmd: Dictionary = item

		# Controllo speaker
		var speaker: String = String(cmd.get("speaker", ""))
		if not speaker.is_empty() and not KNOWN_SPEAKERS.has(speaker):
			errors.append("Riga %d: Personaggio sconosciuto '%s'." % [i, speaker])

		var cmd_type: String = String(cmd.get("type", ""))

		# Controllo salti
		if cmd_type == "jump":
			var target: String = String(cmd.get("target", ""))
			if not declared_labels.has(target):
			errors.append("Riga %d: Salto a etichetta inesistente '%s'." % [i, target])

		# Controllo opzioni delle scelte
		if cmd_type == "choice":
			var options: Variant = cmd.get("options", [])
			if options is Array:
				for opt in options:
					if opt is Dictionary:
						var opt_target: String = String(opt.get("target", ""))
						if not declared_labels.has(opt_target):
							errors.append("Riga %d: Opzione con salto a etichetta inesistente '%s'." % [i, opt_target])

	return errors
